 dict(id=401,slug='animal-observation-versus-motive',title='What did you see?',hook='An action and an explanation are different statements.',q='A video shows an animal scratching a branch. Which statement records the directly visible action?',options=['It scratched the branch','It wanted attention','It felt embarrassed'],answer=0,explain='The first panel describes the visible movement: the animal scratches the branch. The other describes a possible motive, which the video alone does not establish. An interpretation may be worth testing, but it is not the same as the observed action.',recallq='A bird pecks a door. Which sentence is a direct observation?',recalloptions=['The bird pecked the door','The bird wanted revenge','The bird felt lonely'],recallwhy='Pecking is visible; the stated motives are interpretations.',left='<path d="M30 96 V25 M25 45 L64 31" stroke="#a2896a" strokeWidth="7"/><circle cx="98" cy="61" r="20" fill="#c7b4a1"/><path d="M85 72 L62 45" stroke="#8f7866" strokeWidth="5"/><text x="76" y="120" textAnchor="middle" fill="var(--fg)" fontSize="12">Scratches branch</text>',right='<circle cx="60" cy="73" r="22" fill="#c7b4a1"/><path d="M85 45 Q105 18 128 42 Q142 68 109 72 Q94 71 85 59Z" fill="#dce6e8" stroke="#9eafb3"/><text x="108" y="55" textAnchor="middle" fill="var(--fg)" fontSize="18">?</text><text x="76" y="120" textAnchor="middle" fill="var(--fg)" fontSize="12">Possible motive</text>',source=source),
 dict(id=402,slug='animal-cue-controlled-comparison',title='Change one condition',hook='A fair comparison keeps track of what changed.',q='In a toy test of one sound cue, which design better isolates the cue: change only the sound, or change sound and food together?',options=['Change only the sound','Change sound and food together','Neither can be compared'],answer=0,explain='The first comparison keeps the food the same and changes the cue; the second changes both sound and food. The first makes the sound contrast more interpretable, assuming other conditions are controlled and trials are repeated. This is a design, not a measured result.',recallq='To test whether a light cue affects a choice, what should be held the same across the comparison?',recalloptions=['Other relevant conditions','The light cue itself','Nothing else'],recallwhy='Holding relevant conditions constant helps isolate the manipulated cue.',left='<text x="75" y="31" textAnchor="middle" fill="var(--fg)" fontSize="12">Cue changes</text><path d="M25 48 H125" stroke="#72a3b7" strokeWidth="3"/><text x="75" y="78" textAnchor="middle" fill="var(--fg)" fontSize="12">Food stays same</text><text x="75" y="110" textAnchor="middle" fill="var(--fg)" fontSize="12">One change</text>',right='<text x="75" y="31" textAnchor="middle" fill="var(--fg)" fontSize="12">Cue changes</text><path d="M25 48 H125" stroke="#72a3b7" strokeWidth="3"/><text x="75" y="78" textAnchor="middle" fill="var(--fg)" fontSize="12">Food changes too</text><text x="75" y="110" textAnchor="middle" fill="var(--fg)" fontSize="12">Two changes</text>',source=toy),
 dict(id=403,slug='animal-two-observations-limit',title='Two animals, one visit',hook='A small observation has a limited reach.',q='In one visit, animal A approaches a novel object and animal B stays back. What does that observation alone establish?',options=['Those two actions occurred in that visit','Every member of the species approaches','No member of the species ever approaches'],answer=0,explain='The panels show different actions by two individuals in one stipulated observation. That supports a statement about those actions, not a species-wide rule or a reliable frequency. A larger, representative and repeated study would be needed for broader inference.',recallq='One bird uses a tool during one observed visit. What can that visit alone establish?',recalloptions=['That bird used a tool then','All birds always use tools','No other birds ever use tools'],recallwhy='One observation establishes the observed event, not a universal frequency.',left='<circle cx="35" cy="68" r="14" fill="#bba48c"/><path d="M54 68 H94 M84 60 L94 68 L84 76" stroke="#83a6ad" strokeWidth="3" fill="none"/><rect x="105" y="52" width="22" height="32" fill="#dbb777"/><text x="75" y="120" textAnchor="middle" fill="var(--fg)" fontSize="12">A approaches</text>',right='<circle cx="35" cy="68" r="14" fill="#bba48c"/><rect x="105" y="52" width="22" height="32" fill="#dbb777"/><text x="75" y="120" textAnchor="middle" fill="var(--fg)" fontSize="12">B stays back</text>',source=toy),
 dict(id=404,slug='animal-habituation-toy-response',title='A cue repeated',hook='A repeated event can be met with a changing response.',q='In this toy record, responses to the same harmless cue are 4, 3, 2, then 1. What happens across those four trials?',options=['The response decreases','The response increases','It stays exactly the same'],answer=0,explain='The two panels show response levels 4, 3, 2 and 1 across the stipulated trials. The response decreases in this example, a pattern consistent with habituation. The record alone does not rule out fatigue, sensory changes or other explanations.',recallq='A response has levels 5, 4, 3, 2 after four repeated cues. What is the visible trend?',recalloptions=['Decreasing','Increasing','Constant'],recallwhy='The listed values decrease from one trial to the next.',left='<path d="M24 102 H125 M25 102 V23" stroke="var(--line)" strokeWidth="2"/><rect x="45" y="30" width="22" height="72" fill="#d5a26f"/><rect x="82" y="48" width="22" height="54" fill="#d5a26f"/><text x="56" y="120" textAnchor="middle" fill="var(--fg)" fontSize="12">1</text><text x="93" y="120" textAnchor="middle" fill="var(--fg)" fontSize="12">2</text><text x="56" y="26" textAnchor="middle" fill="var(--fg)" fontSize="12">4</text><text x="93" y="43" textAnchor="middle" fill="var(--fg)" fontSize="12">3</text>',right='<path d="M24 102 H125 M25 102 V23" stroke="var(--line)" strokeWidth="2"/><rect x="45" y="66" width="22" height="36" fill="#d5a26f"/><rect x="82" y="84" width="22" height="18" fill="#d5a26f"/><text x="56" y="120" textAnchor="middle" fill="var(--fg)" fontSize="12">3</text><text x="93" y="120" textAnchor="middle" fill="var(--fg)" fontSize="12">4</text><text x="56" y="61" textAnchor="middle" fill="var(--fg)" fontSize="12">2</text><text x="93" y="79" textAnchor="middle" fill="var(--fg)" fontSize="12">1</text>',source=toy),
 dict(id=405,slug='animal-increased-response-toy',title='A response that grows',hook='Repeated events do not always have the same effect.',q='In this toy record, response levels after four cues are 1, 2, 3, 4. What pattern is shown?',options=['An increasing response','A decreasing response','A constant response'],answer=0,explain='The response rises from 1 to 4 across the four stipulated trials. An increasing response may be consistent with sensitization, while a decreasing response may be consistent with habituation. A single sequence does not by itself prove the underlying mechanism.',recallq='A toy response changes from 2 to 4 to 6 across three cues. Which trend is shown?',recalloptions=['Increasing','Decreasing','Unchanged'],recallwhy='Each listed value is larger than the previous one.',left='<path d="M24 102 H125 M25 102 V23" stroke="var(--line)" strokeWidth="2"/><rect x="45" y="84" width="22" height="18" fill="#8cb7b2"/><rect x="82" y="66" width="22" height="36" fill="#8cb7b2"/><text x="56" y="120" textAnchor="middle" fill="var(--fg)" fontSize="12">1</text><text x="93" y="120" textAnchor="middle" fill="var(--fg)" fontSize="12">2</text><text x="56" y="79" textAnchor="middle" fill="var(--fg)" fontSize="12">1</text><text x="93" y="61" textAnchor="middle" fill="var(--fg)" fontSize="12">2</text>',right='<path d="M24 102 H125 M25 102 V23" stroke="var(--line)" strokeWidth="2"/><rect x="45" y="48" width="22" height="54" fill="#8cb7b2"/><rect x="82" y="30" width="22" height="72" fill="#8cb7b2"/><text x="56" y="120" textAnchor="middle" fill="var(--fg)" fontSize="12">3</text><text x="93" y="120" textAnchor="middle" fill="var(--fg)" fontSize="12">4</text><text x="56" y="43" textAnchor="middle" fill="var(--fg)" fontSize="12">3</text><text x="93" y="26" textAnchor="middle" fill="var(--fg)" fontSize="12">4</text>',source=toy),
 dict(id=410,slug='animal-imitation-evidence',title='Same action, why?',hook='Two matching actions can have different explanations.',q='Two animals both open the same box. What additional evidence would best help test whether one copied the other?',options=['Compare observers with similar animals that did not observe','Assume matching actions prove copying','Record only the box color'],answer=0,explain='Both panels show the same final action, but only one includes an observed demonstration. Comparing otherwise similar animals with and without the demonstration can help test whether observing changes later behavior. A matching action by itself does not prove imitation.',recallq='Two animals reach the same food. To investigate whether one learned from watching, what comparison is useful?',recalloptions=['Similar animals with and without a demonstration','Only the size of the food','Only whether both are animals'],recallwhy='A comparison with and without the demonstration can help isolate its contribution.',left='<circle cx="32" cy="52" r="13" fill="#bba48c"/><path d="M47 52 H83 M73 43 L83 52 L73 61" stroke="#83a6ad" strokeWidth="3" fill="none"/><rect x="95" y="40" width="27" height="27" fill="#d9b878"/><text x="75" y="106" textAnchor="middle" fill="var(--fg)" fontSize="12">Demonstration</text>',right='<circle cx="32" cy="52" r="13" fill="#bba48c"/><rect x="95" y="40" width="27" height="27" fill="#d9b878"/><text x="75" y="106" textAnchor="middle" fill="var(--fg)" fontSize="12">No demonstration</text>',source=toy),
 dict(id=412,slug='animal-landmark-to-food',title='A landmark on the way',hook='A familiar object can mark a place.',q='In this toy map, food is next to the tree. If the animal uses that landmark, where should it search?',options=['Next to the tree','Next to the stone','At the empty start'],answer=0,explain='The first panel places food beside the tree; the second shows the route toward the same landmark. A landmark can provide a spatial cue, but this stipulated example does not show that a real animal learned the route or which cues it used.',recallq='A toy food cache is placed beside a rock. Which landmark marks its location?',recalloptions=['The rock','An unrelated cloud','An empty starting point'],recallwhy='In the stipulated example the rock identifies the food location.',left='<circle cx="48" cy="49" r="20" fill="#a7c7a0"/><path d="M48 69 V101" stroke="#9c8269" strokeWidth="6"/><circle cx="78" cy="97" r="7" fill="#d29b69"/><text x="75" y="126" textAnchor="middle" fill="var(--fg)" fontSize="12">Food by tree</text>',right='<circle cx="48" cy="49" r="20" fill="#a7c7a0"/><path d="M48 69 V101" stroke="#9c8269" strokeWidth="6"/><path d="M123 91 H83 M93 81 L83 91 L93 101" stroke="#7aa4b2" strokeWidth="3" fill="none"/><text x="75" y="126" textAnchor="middle" fill="var(--fg)" fontSize="12">Route to tree</text>',source=toy),
 dict(id=426,slug='animal-hearing-ear-arrival',title='Two ears, two times',hook='A tiny timing difference can carry direction.',q='In a toy model a sound reaches the left ear at 4 ms and the right ear at 6 ms. Which ear receives it first?',options=['The left ear','The right ear','They receive it simultaneously'],answer=0,explain='The stipulated arrival times are 4 ms at the left ear and 6 ms at the right ear: left is earlier by 2 ms. Some animals can use differences between ears as directional cues. These values are invented for the comparison, not measured sensory thresholds.',recallq='In a new toy case a sound reaches the right ear at 3 ms and the left ear at 5 ms. Which receives it first?',recalloptions=['The right ear','The left ear','Both at the same time'],recallwhy='3 ms is earlier than 5 ms.',left='<path d="M75 27 Q40 45 42 82 Q44 108 75 110" fill="none" stroke="#b58f72" strokeWidth="6"/><text x="75" y="63" textAnchor="middle" fill="var(--fg)" fontSize="14">Left ear</text><text x="75" y="90" textAnchor="middle" fill="var(--fg)" fontSize="16">4 ms</text>',right='<path d="M75 27 Q110 45 108 82 Q106 108 75 110" fill="none" stroke="#b58f72" strokeWidth="6"/><text x="75" y="63" textAnchor="middle" fill="var(--fg)" fontSize="14">Right ear</text><text x="75" y="90" textAnchor="middle" fill="var(--fg)" fontSize="16">6 ms</text>',source=toy),
 dict(id=439,slug='animal-group-dilution-toy',title='One selected at random',hook='A fixed number of selections can be shared differently.',q='In a toy model one member is chosen uniformly from a group. Is an individual’s chance smaller in a group of 3 or a group of 6?',options=['A group of 6','A group of 3','It is the same in both'],answer=0,explain='With one uniformly selected individual, each member has chance 1/3 in the first group and 1/6 in the second. This is dilution under explicit assumptions, not a general prediction about real predator behavior or group safety.',recallq='One member is chosen uniformly from a group of 10. What is each member’s chance?',recalloptions=['1 in 10','1 in 2','Certain'],recallwhy='One uniformly chosen member among ten gives each member probability 1/10.',left='<circle cx="40" cy="62" r="12" fill="#c3aa8e"/><circle cx="75" cy="62" r="12" fill="#c3aa8e"/><circle cx="110" cy="62" r="12" fill="#c3aa8e"/><text x="75" y="110" textAnchor="middle" fill="var(--fg)" fontSize="14">1 of 3</text>',right='<circle cx="40" cy="45" r="10" fill="#c3aa8e"/><circle cx="75" cy="45" r="10" fill="#c3aa8e"/><circle cx="110" cy="45" r="10" fill="#c3aa8e"/><circle cx="40" cy="77" r="10" fill="#c3aa8e"/><circle cx="75" cy="77" r="10" fill="#c3aa8e"/><circle cx="110" cy="77" r="10" fill="#c3aa8e"/><text x="75" y="110" textAnchor="middle" fill="var(--fg)" fontSize="14">1 of 6</text>',source=toy),
 dict(id=440,slug='animal-vigilance-time-budget',title='Ten minutes to spend',hook='One activity can use time another activity could have used.',q='A toy animal has 10 minutes total. Which schedule spends more time feeding: 8 feeding and 2 watching, or 4 feeding and 6 watching?',options=['8 feeding and 2 watching','4 feeding and 6 watching','They use equal feeding time'],answer=0,explain='Both toy schedules total 10 minutes. The first spends 8 minutes feeding and the second spends 4, so the first has 4 more minutes of feeding. This bookkeeping illustrates a time budget; it does not measure real food intake or safety.',recallq='A toy schedule has 3 minutes watching out of 10, with all remaining time feeding. How many minutes feed?',recalloptions=['7 minutes','3 minutes','13 minutes'],recallwhy='10 total minutes minus 3 watching leaves 7 feeding.',left='<rect x="20" y="45" width="88" height="26" fill="#9dc5a0"/><rect x="108" y="45" width="22" height="26" fill="#e0ba80"/><text x="75" y="98" textAnchor="middle" fill="var(--fg)" fontSize="14">Feed 8 · Watch 2</text>',right='<rect x="20" y="45" width="44" height="26" fill="#9dc5a0"/><rect x="64" y="45" width="66" height="26" fill="#e0ba80"/><text x="75" y="98" textAnchor="middle" fill="var(--fg)" fontSize="14">Feed 4 · Watch 6</text>',source=toy),
 dict(id=441,slug='animal-food-patch-net-toy',title='A meal with a journey',hook='The biggest reward is not always the largest net gain.',q='In a toy foraging model, patch A gives 5 energy units and costs 1 to reach; B gives 8 and costs 6. Which has the larger net energy?',options=['Patch A','Patch B','They are equal'],answer=0,explain='Patch A nets 5 − 1 = 4 energy units. Patch B nets 8 − 6 = 2, even though B offers more food. This toy counts only the stated energy benefit and travel cost; real foragers face other costs and uncertainty.',recallq='A new toy patch gives 9 energy units and costs 3 to reach. What is its net energy?',recalloptions=['6 units','12 units','3 units'],recallwhy='9 units of food minus 3 travel units gives a net of 6.',left='<text x="75" y="35" textAnchor="middle" fill="var(--fg)" fontSize="15">Patch A</text><text x="75" y="67" textAnchor="middle" fill="var(--fg)" fontSize="14">Food 5</text><text x="75" y="93" textAnchor="middle" fill="var(--fg)" fontSize="14">Travel −1</text><text x="75" y="121" textAnchor="middle" fill="var(--fg)" fontSize="14">Net 4</text>',right='<text x="75" y="35" textAnchor="middle" fill="var(--fg)" fontSize="15">Patch B</text><text x="75" y="67" textAnchor="middle" fill="var(--fg)" fontSize="14">Food 8</text><text x="75" y="93" textAnchor="middle" fill="var(--fg)" fontSize="14">Travel −6</text><text x="75" y="121" textAnchor="middle" fill="var(--fg)" fontSize="14">Net 2</text>',source=toy),
