 meta={'slug':c['slug'],'title':c['title'],'hook':c['hook'],'domain':'life','concept':c['slug'],'status':'draft','durationSec':60,'owner':{'categoryManager':'cm-life','builder':'demo-builder'},'learner':{'knows':['Animals can act and respond to conditions.'],'doesNotKnow':[c['q']]},'misconception':'One observed behavior always supports a broad or causal conclusion.','objective':c['q'],'claims':[{'id':f"life.{c['slug']}.c1",'text':c['q']+' '+c['explain'],'support':'source','source':c['source'],'status':'unverified'},{'id':f"life.{c['slug']}.c2",'text':'The panels show a stipulated illustrative scenario, not observations or measurements of real animals.','support':'convention','source':'Diagram convention','status':'unverified'},{'id':f"life.{c['slug']}.c3",'text':c['recallq']+' '+c['recallwhy'],'support':'source','source':c['source'],'status':'unverified'}],'confidence':'','recall':recall,'evidence':{'qa':[],'simulatedLearner':[],'pairwise':[],'humanLearners':[]},'version':2 if c['id'] in [401,410] else 1}
